from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one match, found {count}")
    return text.replace(old, new, 1)


repo = Path("web/services/vms/repository.ts")
text = repo.read_text()
text = replace_once(
    text,
    '''  readonly claimStaleCreateAttempt?: (input: {\n    readonly id: string;\n    readonly before: Date;\n  }) => Effect.Effect<CloudVmRow | null, VmDatabaseError>;\n''',
    '''  readonly markCreateAttemptReady?: (id: string) => Effect.Effect<CloudVmRow, VmDatabaseError>;\n  readonly claimStaleCreateAttempt?: (input: {\n    readonly id: string;\n    readonly before: Date;\n  }) => Effect.Effect<CloudVmRow | null, VmDatabaseError>;\n''',
    "repository ready shape",
)
text = replace_once(
    text,
    '''  claimStaleCreateAttempt: (input) =>\n    dbEffect("claimStaleCreateAttempt", async () => {\n''',
    '''  markCreateAttemptReady: (id) =>\n    dbEffect("markCreateAttemptReady", async () => {\n      const db = cloudDb();\n      const [vm] = await db\n        .update(cloudVms)\n        .set({\n          providerMetadata: sql`coalesce(${cloudVms.providerMetadata}, '{}'::jsonb) || '{"providerCreateReady":true}'::jsonb`,\n          updatedAt: new Date(),\n        })\n        .where(and(\n          eq(cloudVms.id, id),\n          eq(cloudVms.status, "provisioning"),\n          eq(cloudVms.provider, "blaxel"),\n          isNull(cloudVms.providerVmId),\n          sql`coalesce(${cloudVms.providerMetadata} ->> 'createIdentity', '') <> ''`,\n        ))\n        .returning();\n      if (!vm) throw new Error(`create attempt ${id} is no longer provider-eligible`);\n      return vm;\n    }),\n\n  claimStaleCreateAttempt: (input) =>\n    dbEffect("claimStaleCreateAttempt", async () => {\n''',
    "repository ready implementation",
)
text = replace_once(
    text,
    '''          eq(cloudVms.status, "provisioning"),\n          isNull(cloudVms.providerVmId),\n          lt(cloudVms.updatedAt, input.before),\n''',
    '''          eq(cloudVms.status, "provisioning"),\n          eq(cloudVms.provider, "blaxel"),\n          isNull(cloudVms.providerVmId),\n          lt(cloudVms.updatedAt, input.before),\n          sql`coalesce(${cloudVms.providerMetadata} ->> 'providerCreateReady', 'false') = 'true'`,\n          sql`coalesce(${cloudVms.providerMetadata} ->> 'createIdentity', '') <> ''`,\n''',
    "stale claim durable fence",
)
repo.write_text(text)

provider_errors = Path("web/services/vms/providerErrors.ts")
text = provider_errors.read_text()
marker = '''\nexport const PROVIDER_CREATE_INDETERMINATE_CODE = "provider_create_indeterminate";\n\n/**\n * The provider may have committed a create, but the client cannot yet prove\n * either success or absence. Billing and the durable attempt identity must be\n * retained until the exact attempt is reconciled.\n */\nexport class ProviderCreateIndeterminateError extends Error {\n  readonly code = PROVIDER_CREATE_INDETERMINATE_CODE;\n\n  constructor(message: string, public readonly cause?: unknown) {\n    super(message);\n    this.name = "ProviderCreateIndeterminateError";\n  }\n}\n\nexport function isProviderCreateIndeterminateError(err: unknown): boolean {\n  if (!err || typeof err !== "object") return false;\n  const candidate = err as {\n    readonly code?: unknown;\n    readonly name?: unknown;\n    readonly cause?: unknown;\n  };\n  if (candidate.code === PROVIDER_CREATE_INDETERMINATE_CODE) return true;\n  if (candidate.name === "ProviderCreateIndeterminateError") return true;\n  return candidate.cause !== err && isProviderCreateIndeterminateError(candidate.cause);\n}\n'''
if "PROVIDER_CREATE_INDETERMINATE_CODE" in text:
    raise SystemExit("provider indeterminate marker already exists")
provider_errors.write_text(text.rstrip() + "\n" + marker)

blaxel = Path("web/services/vms/drivers/blaxel.ts")
text = blaxel.read_text()
text = replace_once(
    text,
    '''import { VmOperationUnsupportedError } from "../errors";\n''',
    '''import { VmOperationUnsupportedError } from "../errors";\nimport { ProviderCreateIndeterminateError } from "../providerErrors";\n''',
    "blaxel indeterminate import",
)
old_ambiguous = '''              if (createIdentity && ambiguousSandboxCreateFailure(err)) {\n                try {\n                  const recovered = await timedStep("recover_ambiguous_create", () => this.getSandbox(name));\n                  const recoveredName = recovered.metadata?.name?.trim();\n                  if (recoveredName && recoveredName !== name) {\n                    throw new ProviderError(\n                      "blaxel",\n                      `recovered sandbox identity mismatch: expected ${name}, got ${recoveredName}`,\n                    );\n                  }\n                  const recoveredImage = recovered.spec?.runtime?.image?.trim();\n                  if (recoveredImage && recoveredImage !== image) {\n                    throw new ProviderError(\n                      "blaxel",\n                      `recovered sandbox ${name} uses unexpected image ${recoveredImage}`,\n                    );\n                  }\n                  created = recovered;\n                  break;\n                } catch (recoveryErr) {\n                  // A failed or stale read is not proof that the POST had no effect.\n                  // Preserve any just-created per-machine volume; the same-key retry\n                  // reuses this create identity, sandbox name, and volume name.\n                  if (!(recoveryErr instanceof ProviderError && /-> 404/.test(recoveryErr.message))) {\n                    console.warn(`[blaxel] ambiguous create recovery for ${name} failed`, recoveryErr);\n                  }\n                  throw err;\n                }\n              }\n'''
new_ambiguous = '''              if (createIdentity && ambiguousSandboxCreateFailure(err)) {\n                let recovered: BlaxelSandbox;\n                try {\n                  recovered = await timedStep("recover_ambiguous_create", () => this.getSandbox(name));\n                } catch (recoveryErr) {\n                  // A failed or stale read is not proof that the POST had no effect.\n                  // Preserve any just-created per-machine volume; the same-key retry\n                  // reuses this create identity, sandbox name, and volume name. Mark\n                  // the outcome explicitly so the workflow retains the billing debit\n                  // while it waits to reconcile this exact provider attempt.\n                  if (!(recoveryErr instanceof ProviderError && /-> 404/.test(recoveryErr.message))) {\n                    console.warn(`[blaxel] ambiguous create recovery for ${name} failed`, recoveryErr);\n                  }\n                  throw new ProviderCreateIndeterminateError(\n                    `Blaxel sandbox create ${name} may have committed but could not be reconciled`,\n                    { createError: err, recoveryError: recoveryErr },\n                  );\n                }\n                const recoveredName = recovered.metadata?.name?.trim();\n                if (recoveredName && recoveredName !== name) {\n                  throw new ProviderError(\n                    "blaxel",\n                    `recovered sandbox identity mismatch: expected ${name}, got ${recoveredName}`,\n                  );\n                }\n                const recoveredImage = recovered.spec?.runtime?.image?.trim();\n                if (recoveredImage && recoveredImage !== image) {\n                  throw new ProviderError(\n                    "blaxel",\n                    `recovered sandbox ${name} uses unexpected image ${recoveredImage}`,\n                  );\n                }\n                created = recovered;\n                break;\n              }\n'''
text = replace_once(text, old_ambiguous, new_ambiguous, "blaxel ambiguous outcome marker")
blaxel.write_text(text)

workflows = Path("web/services/vms/workflows.ts")
text = workflows.read_text()
text = replace_once(
    text,
    '''  vmWorkflowErrorCause,\n  type VmDatabaseError,\n  type VmWorkflowError,\n''',
    '''  VmDatabaseError,\n  vmWorkflowErrorCause,\n  type VmWorkflowError,\n''',
    "workflow database error import",
)
text = replace_once(
    text,
    '''import { isProviderIdentityNotFoundError, isProviderNotFoundError } from "./providerErrors";\n''',
    '''import {\n  isProviderCreateIndeterminateError,\n  isProviderIdentityNotFoundError,\n  isProviderNotFoundError,\n} from "./providerErrors";\n''',
    "workflow provider error import",
)
create_start = text.index("export function createVm(")
create_end = text.index("\nexport function openBaseVm", create_start)
create_segment = text[create_start:create_end]
create_segment = replace_once(
    create_segment,
    '''          typeof createIdentity === "string" &&\n          createIdentity.trim() &&\n          repo.claimStaleCreateAttempt\n''',
    '''          typeof createIdentity === "string" &&\n          createIdentity.trim() &&\n          existing.providerMetadata?.providerCreateReady === true &&\n          repo.claimStaleCreateAttempt\n''',
    "stale replay fence",
)
create_segment = replace_once(
    create_segment,
    '''              Effect.tapError((err) =>\n                repo.recordUsageEvent({\n                  userId: input.userId,\n                  billingTeamId: input.billingTeamId,\n                  billingPlanId: input.billingPlanId,\n                  vmId: claimed.id,\n                  eventType: "vm.create.reconcile_failed",\n                  provider: input.provider,\n                  imageId: input.image,\n                  metadata: { operation: err.operation, message: errorMessage(err.cause) },\n                }).pipe(Effect.catchAll(() => Effect.void)),\n              ),\n''',
    '''              Effect.tapError((err) =>\n                repo.recordUsageEvent({\n                  userId: input.userId,\n                  billingTeamId: input.billingTeamId,\n                  billingPlanId: input.billingPlanId,\n                  vmId: claimed.id,\n                  eventType: isProviderCreateIndeterminateError(err)\n                    ? "vm.create.reconcile_pending"\n                    : "vm.create.reconcile_failed",\n                  provider: input.provider,\n                  imageId: input.image,\n                  metadata: {\n                    operation: err.operation,\n                    message: errorMessage(err.cause),\n                    billingReservationRetained: true,\n                  },\n                }).pipe(Effect.catchAll(() => Effect.void)),\n              ),\n''',
    "resume observability",
)
old_fresh = '''    const creditReservation = yield* reserveCreateCredit(billing, repo, input, create.vm);\n    yield* recordCreateRequestedEvents(repo, input, create.vm, creditReservation);\n\n    const handle = yield* measureVmEffect(\n      input.timing,\n      "provider_create",\n      providers.create(input.provider, {\n        image: input.image,\n        providerMetadata: create.vm.providerMetadata,\n        bakedFreestyleSignedAdmin: input.bakedFreestyleSignedAdmin,\n        homeVolume: input.perMachineHome\n          ? homeVolumeTemplateForUser(input.userId)\n          : input.persistentHome\n            ? homeVolumeNameForUser(input.userId)\n            : undefined,\n        memoryMb: input.memoryMb,\n        envs: input.envs,\n      }),\n    ).pipe(\n      Effect.tapError((err) =>\n        Effect.all([\n          refundCredit(billing, repo, create.vm, creditReservation),\n          repo.markCreateFailed({\n            id: create.vm.id,\n            // providers.create fails only with VmProviderOperationError, and\n            // the caller is told it is retryable (vm_cloud_service_unavailable,\n            // retryAfterSeconds ~5), so store the code that lets a same-key\n            // retry reach the provider again immediately.\n            code: PROVIDER_CREATE_UNAVAILABLE_FAILURE_CODE,\n            message: errorMessage(err.cause),\n          }),\n          repo.recordUsageEvent({\n            userId: input.userId,\n            billingTeamId: input.billingTeamId,\n            billingPlanId: input.billingPlanId,\n            vmId: create.vm.id,\n            eventType: "vm.create.failed",\n            provider: input.provider,\n            imageId: input.image,\n            metadata: { operation: err.operation, message: errorMessage(err.cause) },\n          }),\n        ], { discard: true }).pipe(Effect.catchAll(() => Effect.void))\n      ),\n    );\n\n    const running = yield* measureVmEffect(\n      input.timing,\n      "mark_running",\n      repo.markCreateRunning({\n        id: create.vm.id,\n        providerVmId: handle.providerVmId,\n        image: handle.image,\n        imageVersion: input.imageVersion ?? null,\n        providerMetadata: handle.providerMetadata ?? create.vm.providerMetadata,\n      }),\n    ).pipe(\n      Effect.catchAll((err) =>\n        Effect.gen(function* () {\n          yield* rollbackProviderCreate(providers, input.provider, handle);\n          yield* refundCredit(billing, repo, create.vm, creditReservation);\n          yield* repo.markCreateFailed({\n            id: create.vm.id,\n            code: "database_finalize_failed",\n            message: "Cloud VM state update failed.",\n          }).pipe(Effect.catchAll(() => Effect.void));\n          yield* recordCreateFailureEvent(\n            repo,\n            input,\n            create.vm,\n            "database_finalize_failed",\n            errorMessage(err.cause),\n          ).pipe(Effect.catchAll(() => Effect.void));\n          return yield* Effect.fail(err);\n        }),\n      ),\n    );\n\n    yield* recordCreateSuccessEvents(repo, input, running);\n\n    return vmEntryFromRow(running);\n'''
new_fresh = '''    const creditReservation = yield* reserveCreateCredit(billing, repo, input, create.vm);\n\n    let providerCreateVm = create.vm;\n    if (input.provider === "blaxel") {\n      const markCreateAttemptReady = repo.markCreateAttemptReady;\n      if (!markCreateAttemptReady) {\n        return yield* Effect.fail(new VmDatabaseError({\n          operation: "markCreateAttemptReady",\n          cause: new Error("Blaxel provider-start fencing is unavailable"),\n        }));\n      }\n      // Stack's item decrement has no external operation identity. Provider work\n      // is therefore permitted only after billing returned success and this bit\n      // is durably committed. If the process dies earlier, restart fails closed\n      // instead of replaying either billing or provider create.\n      providerCreateVm = yield* measureVmEffect(\n        input.timing,\n        "mark_provider_create_ready",\n        markCreateAttemptReady(create.vm.id),\n      );\n    }\n\n    yield* recordCreateRequestedEvents(repo, input, providerCreateVm, creditReservation);\n\n    const handle = yield* measureVmEffect(\n      input.timing,\n      "provider_create",\n      providers.create(input.provider, {\n        image: input.image,\n        providerMetadata: providerCreateVm.providerMetadata,\n        bakedFreestyleSignedAdmin: input.bakedFreestyleSignedAdmin,\n        homeVolume: input.perMachineHome\n          ? homeVolumeTemplateForUser(input.userId)\n          : input.persistentHome\n            ? homeVolumeNameForUser(input.userId)\n            : undefined,\n        memoryMb: input.memoryMb,\n        envs: input.envs,\n      }),\n    ).pipe(\n      Effect.tapError((err) =>\n        isProviderCreateIndeterminateError(err)\n          ? repo.recordUsageEvent({\n              userId: input.userId,\n              billingTeamId: input.billingTeamId,\n              billingPlanId: input.billingPlanId,\n              vmId: providerCreateVm.id,\n              eventType: "vm.create.reconcile_pending",\n              provider: input.provider,\n              imageId: input.image,\n              metadata: {\n                operation: err.operation,\n                message: errorMessage(err.cause),\n                billingReservationRetained: creditReservation.kind !== "none",\n              },\n            }).pipe(Effect.catchAll(() => Effect.void))\n          : Effect.all([\n              refundCredit(billing, repo, providerCreateVm, creditReservation),\n              repo.markCreateFailed({\n                id: providerCreateVm.id,\n                // A definite provider create failure is safe to compensate and\n                // retry. Indeterminate outcomes stay provisioning above so the\n                // same external attempt is reconciled without refund/re-reserve.\n                code: PROVIDER_CREATE_UNAVAILABLE_FAILURE_CODE,\n                message: errorMessage(err.cause),\n              }),\n              repo.recordUsageEvent({\n                userId: input.userId,\n                billingTeamId: input.billingTeamId,\n                billingPlanId: input.billingPlanId,\n                vmId: providerCreateVm.id,\n                eventType: "vm.create.failed",\n                provider: input.provider,\n                imageId: input.image,\n                metadata: { operation: err.operation, message: errorMessage(err.cause) },\n              }),\n            ], { discard: true }).pipe(Effect.catchAll(() => Effect.void))\n      ),\n    );\n\n    const running = yield* measureVmEffect(\n      input.timing,\n      "mark_running",\n      repo.markCreateRunning({\n        id: providerCreateVm.id,\n        providerVmId: handle.providerVmId,\n        image: handle.image,\n        imageVersion: input.imageVersion ?? null,\n        providerMetadata: handle.providerMetadata ?? providerCreateVm.providerMetadata,\n      }),\n    ).pipe(\n      Effect.catchAll((err) =>\n        Effect.gen(function* () {\n          yield* rollbackProviderCreate(providers, input.provider, handle);\n          yield* refundCredit(billing, repo, providerCreateVm, creditReservation);\n          yield* repo.markCreateFailed({\n            id: providerCreateVm.id,\n            code: "database_finalize_failed",\n            message: "Cloud VM state update failed.",\n          }).pipe(Effect.catchAll(() => Effect.void));\n          yield* recordCreateFailureEvent(\n            repo,\n            input,\n            providerCreateVm,\n            "database_finalize_failed",\n            errorMessage(err.cause),\n          ).pipe(Effect.catchAll(() => Effect.void));\n          return yield* Effect.fail(err);\n        }),\n      ),\n    );\n\n    yield* recordCreateSuccessEvents(repo, input, running);\n\n    return vmEntryFromRow(running);\n'''
create_segment = replace_once(create_segment, old_fresh, new_fresh, "fresh provider protocol")
text = text[:create_start] + create_segment + text[create_end:]
workflows.write_text(text)
